function treeHtml(){const sorted=units.slice().sort((a,b)=>a.name.localeCompare(b.name,'vi'));const map=unitMap();const roots=sorted.filter(u=>!map.has(u.parent_id));const walk=(node,depth=0)=>`<div class="treeitem ${node.kind.toLowerCase()}" style="margin-left:${Math.min(depth*22,80)}px"><div><span class="treekind">${esc(kindLabels[node.kind])}</span><span class="treehead">${esc(node.name)}</span><div class="treecode">${esc(node.code)}</div></div><span class="tag none">${employees.filter(e=>e.unit_id===node.id).length} NV</span></div>`+sorted.filter(u=>u.parent_id===node.id).map(u=>walk(u,depth+1)).join('');return `<div class="tree">${roots.map(u=>walk(u)).join('')||'<p>Chưa có đơn vị.</p>'}</div>`}
