 const kind=$('#unitKind'),parent=$('#parentUnit');const refreshParent=()=>{const k=kind.value;$$('option',parent).forEach(o=>{const unit=getUnit(o.value);o.hidden=!(k==='CN1'?!o.value:k==='CN2'?unit?.kind==='CN1':unit?.kind==='CN1'||unit?.kind==='CN2')});if(!$$('option',parent).find(o=>o.value===parent.value&&!o.hidden))parent.value=$$('option',parent).find(o=>!o.hidden)?.value||''};kind.onchange=refreshParent;kind.value=profile.role==='cn2_admin'?'PHONG':root?'CN1':'CN2';refreshParent();
