function unitEditForm(unit){if(!unit)return;showModal(`<h2>Đổi tên đơn vị</h2><p class="help">Mã ${esc(unit.code)} và cấu trúc trực thuộc vẫn giữ nguyên.</p><form id="unitRename"><div class="field"><label>Tên đơn vị</label><input name="name" maxlength="180" required value="${esc(unit.name)}"/></div><div class="actions"><button type="button" class="btn ghost" data-close>Hủy</button><button class="btn">Lưu tên</button></div></form>`);$('#unitRename').onsubmit=async e=>{e.preventDefault();try{const {error}=await supabase.from('org_units').update({name:new FormData(e.currentTarget).get('name').trim()}).eq('id',unit.id);if(error)postError(error);closeModal();notify('Đã đổi tên đơn vị');await refreshAndRender()}catch(err){showError(err)}}}
