function employeeForm(emp=null){const edit=!!emp;showModal(`<h2>${edit?'Cập nhật / điều chuyển nhân viên':'Đăng ký nhân viên mới'}</h2><p class="sub">${edit?'Mã nhân viên là bất biến, thay phòng/chức vụ không thay ảnh định danh.':'Sau khi lưu hồ sơ, ảnh đã chọn sẽ được đăng ký lên kho ảnh riêng tư.'}</p><form id="employeeForm"><div class="grid2"><div class="field"><label>Mã nhân viên</label><input name="emp_code" pattern="[A-Za-z0-9_-]{2,40}" value="${esc(emp?.emp_code||'')}" ${edit?'readonly':''} required maxlength="40"/></div><div class="field"><label>Họ và tên</label><input name="full_name" value="${esc(emp?.full_name||'')}" required maxlength="150"/></div><div class="field"><label>Đơn vị công tác (cấp phòng)</label><select name="unit_id" required><option value="">-- Chọn phòng --</option>${empUnitOptions(emp?.unit_id||'')}</select></div><div class="field"><label>Chức vụ / vị trí</label><input name="position" value="${esc(emp?.position||'')}" maxlength="150"/></div><div class="field"><label>Ngày bắt đầu công tác</label><input type="date" name="started_on" value="${esc(emp?.started_on||'')}"/></div><div class="field"><label>Trạng thái hồ sơ</label><select name="active"><option value="true" ${emp?.active!==false?'selected':''}>Đang công tác</option><option value="false" ${emp?.active===false?'selected':''}>Ngừng hoạt động</option></select></div></div>${!edit?`<div class="field"><label>Ảnh định danh (1 khuôn mặt, JPG/PNG/WEBP)</label><input type="file" name="photo" id="newEmployeePhoto" accept="image/*"/><p class="help">Có thể bổ sung ảnh sau nếu nhập danh sách từ CSV. Giới hạn 10 MB/ảnh trước khi nén.</p></div>`:''}<div class="actions"><button type="button" class="btn ghost" data-close>Hủy</button><button class="btn" id="saveEmployee">${edit?'Lưu thay đổi':'Tạo hồ sơ'}</button></div></form>`);
 $('#employeeForm').onsubmit=async ev=>{ev.preventDefault();const btn=$('#saveEmployee'),fd=new FormData(ev.currentTarget),unit=fd.get('unit_id');if(!unit)return notify('Phải chọn một phòng',true);btn.disabled=true;
 const record={full_name:fd.get('full_name').trim(),unit_id:unit,position:String(fd.get('position')||'').trim(),started_on:fd.get('started_on')||null,active:fd.get('active')==='true'};
 try{let empid=emp?.id;if(edit){const {error}=await supabase.from('employees').update(record).eq('id',emp.id);if(error)postError(error)}else{const {data,error}=await supabase.from('employees').insert({...record,emp_code:String(fd.get('emp_code')).trim().toUpperCase()}).select('id').single();if(error)postError(error);empid=data.id}
 let faceError='';const file=fd.get('photo');if(!edit&&file instanceof File&&file.size){try{await uploadFace(empid,file)}catch(err){faceError=err.message}}
 closeModal();await refreshAndRender();notify(edit?'Đã lưu thông tin / điều chuyển':'Đã tạo nhân viên');if(faceError)notify('Hồ sơ đã tạo nhưng chưa lưu được ảnh: '+faceError,true)
 }catch(err){showError(err)}finally{btn.disabled=false}}
}
async function sourceImage(file){if(file.size>10*1024*1024)throw Error('Ảnh vượt 10 MB');if(!/^image\/(jpeg|png|webp)$/i.test(file.type))throw Error('Vui lòng dùng ảnh JPG, PNG hoặc WEBP');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();return img}finally{URL.revokeObjectURL(url)}}
async function uploadFace(employeeId,file){const img=await sourceImage(file);const w=img.naturalWidth,h=img.naturalHeight,max=1200,scale=Math.min(1,max/Math.max(w,h));const canvas=document.createElement('canvas');canvas.width=Math.round(w*scale);canvas.height=Math.round(h*scale);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);const descriptor=await faceDescriptor(canvas);
 const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Không xử lý được ảnh')),'image/jpeg',.86));const path=`${employeeId}/${Date.now()}-${Math.random().toString(36).slice(2,9)}.jpg`;
 const {error:upErr}=await supabase.storage.from('employee-faces').upload(path,blob,{contentType:'image/jpeg',upsert:false});if(upErr)postError(upErr);
 const {error:faceErr}=await supabase.rpc('enroll_employee_face',{p_employee:employeeId,p_descriptor:JSON.stringify(descriptor),p_photo_path:path});if(faceErr)postError(faceErr);
 return true;
}
function faceForm(emp){if(!emp)return;showModal(`<h2>Đăng ký / cấp lại ảnh</h2><p class="sub">${esc(emp.full_name)} · Mã NV ${esc(emp.emp_code)}</p><div class="hint mt12">Đăng ký lại ảnh là thao tác riêng, không xảy ra khi điều chuyển. Người sử dụng kính/mũ có thể được mô hình nhận diện, nhưng không bảo đảm đạt ngưỡng trong mọi điều kiện.</div><form id="faceForm"><div class="field"><label>Ảnh mới có đúng 1 khuôn mặt</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required/></div><div class="actions"><button class="btn ghost" type="button" data-close>Hủy</button><button class="btn" id="saveFace">Lưu ảnh định danh</button></div></form>`);
 $('#faceForm').onsubmit=async e=>{e.preventDefault();const file=new FormData(e.currentTarget).get('photo'),b=$('#saveFace');b.disabled=true;try{await uploadFace(emp.id,file);closeModal();notify('Đã lưu ảnh định danh mới');await refreshAndRender()}catch(err){showError(err)}finally{b.disabled=false}};
}
function showHistory(emp){const hist=assignments.filter(h=>h.employee_id===emp.id).sort((a,b)=>a.valid_from.localeCompare(b.valid_from));showModal(`<h2>Lịch sử phòng ban</h2><p class="sub">${esc(emp.full_name)} · Mã NV ${esc(emp.emp_code)}</p><div class="tablewrap mt20"><table><thead><tr><th>Đơn vị</th><th>Từ</th><th>Đến</th></tr></thead><tbody>${hist.map(h=>`<tr><td>${esc(fullUnit(h.unit_id))}</td><td>${esc(new Date(h.valid_from).toLocaleString('vi-VN'))}</td><td>${h.valid_to?esc(new Date(h.valid_to).toLocaleString('vi-VN')):'Đang công tác'}</td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="btn ghost" data-close>Đóng</button></div>`)}
function parseCsv(str){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<str.length;i++){const ch=str[i];if(ch==='"'){if(quoted&&str[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(value);value=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&str[i+1]==='\n')i++;row.push(value);if(row.some(x=>x.trim()))rows.push(row);row=[];value=''}else value+=ch}row.push(value);if(row.some(x=>x.trim()))rows.push(row);return rows}
function csvForm(){showModal(`<h2>Nhập nhân viên từ CSV UTF-8</h2><p class="sub">Cột bắt buộc: <code>ma_nv,ho_ten,ma_don_vi,vi_tri</code>; có thể thêm <code>ngay_vao</code>. Mã đơn vị phải là mã của PHÒNG đã tạo, không phải mã CN loại I/II.</p><div class="hint mt12">Nhân viên trùng mã được bỏ qua, không ghi đè. Ảnh được tải bổ sung riêng theo từng nhân viên.</div><form id="csvForm"><div class="field"><label>Tệp CSV</label><input name="file" type="file" accept=".csv,text/csv" required/></div><div class="actions"><button type="button" class="btn ghost" data-close>Hủy</button><button class="btn" id="runCsv">Nhập danh sách</button></div></form>`);
 $('#csvForm').onsubmit=async e=>{e.preventDefault();const b=$('#runCsv');b.disabled=true;try{const f=new FormData(e.currentTarget).get('file');if(f.size>3e6)throw Error('Giới hạn 3 MB');const rows=parseCsv((await f.text()).replace(/^\ufeff/,''));const headings=rows.shift().map(v=>v.toLowerCase().trim());for(const k of ['ma_nv','ho_ten','ma_don_vi'])if(!headings.includes(k))throw Error('Thiếu cột '+k);
 let ok=0,skipped=0,errors=[];const existing=new Set(employees.map(x=>x.emp_code));for(const row of rows){const get=k=>String(row[headings.indexOf(k)]||'').trim(),code=get('ma_nv').toUpperCase(),unit=units.find(x=>x.code===get('ma_don_vi')&&x.kind==='PHONG');if(existing.has(code)){skipped++;continue}if(!/^[A-Z0-9_-]{2,40}$/.test(code)||!get('ho_ten')||!unit){errors.push(code||'(trống)');continue}const record={emp_code:code,full_name:get('ho_ten'),unit_id:unit.id,position:get('vi_tri'),started_on:get('ngay_vao')||null};const {error}=await supabase.from('employees').insert(record);if(error)errors.push(code+': '+error.message);else{ok++;existing.add(code)}}closeModal();await refreshAndRender();notify(`Đã nhập ${ok}; trùng ${skipped}; lỗi ${errors.length}${errors.length?': '+errors.slice(0,3).join(', '):''}`,!!errors.length)
 }catch(err){showError(err)}finally{b.disabled=false}}
}
// Bao cao tren lich su phan cong: khi dieu chuyen, ngay cu van giu tai don vi cu.
function currentRange(){let start,end;const day=reportAnchor||today();if(rangeMode==='day')start=end=day;else if(rangeMode==='week'){start=monday(day);end=addDay(start,6)}else if(rangeMode==='year'){start=day.slice(0,4)+'-01-01';end=day.slice(0,4)+'-12-31'}else{start=day.slice(0,7)+'-01';end=addDay(addDay(day.slice(0,7)+'-01',32).slice(0,7)+'-01',-1)}return [start,end]}
function datesInRange(){const [a,b]=currentRange(),dates=[];for(let d=a;d<=b&&d<=today();d=addDay(d,1))if(includeWeekend||isWeekday(d))dates.push(d);return dates}
function punchCode(records){if(!records?.length)return '-';const slots=new Set(records.map(r=>r.slot));const has4=records.some(r=>r.mode===4);const am=has4?(slots.has('AM_IN')&&slots.has('AM_OUT')):slots.has('AM');const pm=has4?(slots.has('PM_IN')&&slots.has('PM_OUT')):slots.has('PM');if(am&&pm)return 'X';if(am)return 'Xc';if(pm)return 'Xs';return 'x'}
const markClass=mark=>mark==='X'?'good':mark==='Xc'||mark==='Xs'?'warn':mark==='x'?'none':'';
function assignedDuring(h,date){const start=Date.parse(date+'T00:00:00+07:00'),end=Date.parse(date+'T23:59:59+07:00');return Date.parse(h.valid_from)<=end&&(!h.valid_to||Date.parse(h.valid_to)>start)}
function buildReport(){const dates=datesInRange(),term=reportQuery.toLocaleLowerCase('vi').trim();const seen=new Map();const recordsByKey=new Map();for(const p of punches){const key=`${p.employee_id}|${p.unit_id}|${p.punch_date}`;if(!recordsByKey.has(key))recordsByKey.set(key,[]);recordsByKey.get(key).push(p)}
 for(const h of assignments){if(reportUnit&&!descendants(h.unit_id,reportUnit))continue;if(term&&!`${h.emp_code} ${h.full_name} ${labelUnit(h.unit_id)}`.toLocaleLowerCase('vi').includes(term))continue;
  const startEmployee=employees.find(e=>e.id===h.employee_id)?.started_on;const activeDates=dates.filter(d=>assignedDuring(h,d)&&(!startEmployee||d>=startEmployee));if(!activeDates.length)continue;const key=`${h.employee_id}|${h.unit_id}`;if(!seen.has(key))seen.set(key,{employee_id:h.employee_id,emp_code:h.emp_code,full_name:h.full_name,unit_id:h.unit_id,day:{},counts:{X:0,Xc:0,Xs:0,x:0,'-':0}});
  const row=seen.get(key);for(const d of activeDates){const code=punchCode(recordsByKey.get(`${h.employee_id}|${h.unit_id}|${d}`));row.day[d]=code}
 }
 const result=[...seen.values()].sort((a,b)=>fullUnit(a.unit_id).localeCompare(fullUnit(b.unit_id),'vi')||a.full_name.localeCompare(b.full_name,'vi'));
 for(const r of result){for(const d of dates){const code=r.day[d];if(code!==undefined)r.counts[code]=(r.counts[code]||0)+1}}
 return {dates,rows:result}}
function reportTable(){const {dates,rows}=buildReport();lastReportRows=rows;lastReportDates=dates;
 return `<p class="help mb10">Có ${rows.length} dòng nhân viên/đơn vị theo lịch sử phân công. X: đủ sáng/chiều · Xc: chỉ đủ sáng · Xs: chỉ đủ chiều · x: có lượt nhưng chưa đủ nửa buổi · –: không ghi nhận. Ô trống: chưa thuộc đơn vị.</p><div class="tablewrap"><table class="reportmatrix"><thead><tr><th>STT</th><th>Mã NV</th><th>Họ và tên</th><th>Đơn vị tại kỳ báo cáo</th>${dates.map(d=>`<th title="${dateVN(d)}">${esc(d.slice(8))}</th>`).join('')}<th>X</th><th>Xc</th><th>Xs</th><th>x</th><th>–</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td class="code">${esc(r.emp_code)}</td><td><button class="btn ghost small" data-report-person="${r.employee_id}" data-report-unit="${r.unit_id}">${esc(r.full_name)}</button></td><td>${esc(fullUnit(r.unit_id))}</td>${dates.map(d=>`<td><span class="tag ${markClass(r.day[d])}">${r.day[d]===undefined?'':esc(r.day[d])}</span></td>`).join('')}<td>${r.counts.X||0}</td><td>${r.counts.Xc||0}</td><td>${r.counts.Xs||0}</td><td>${r.counts.x||0}</td><td>${r.counts['-']||0}</td></tr>`).join('')}</tbody></table></div>`}
function renderReports(container){const [from,to]=currentRange();container.innerHTML=`<div class="hero"><div><h2>Báo cáo tuần · tháng · năm</h2><p>Tổng hợp toàn CN loại I hoặc theo từng CN loại II được cấp quyền, thống kê ngày thiếu điểm danh của từng cán bộ.</p></div><button class="btn light" id="exportExcel">Xuất Excel (.xlsx)</button></div><div class="panel"><div class="row between"><div class="pillline" id="rangePicker">${[['day','Theo ngày'],['week','Theo tuần'],['month','Theo tháng'],['year','Theo năm']].map(([key,text])=>`<button class="pill ${rangeMode===key?'active':''}" data-mode="${key}">${text}</button>`).join('')}</div><label class="radio-label tiny"><input type="checkbox" id="weekend" ${includeWeekend?'checked':''}/> Gồm thứ Bảy, Chủ nhật</label></div><div class="filterbar mt20"><div class="field"><label>Ngày mốc</label><input type="date" id="reportAnchor" value="${esc(reportAnchor)}"/></div><div class="field"><label>Chi nhánh / phòng</label><select id="reportUnit"><option value="">Tất cả phạm vi được cấp</option>${units.map(u=>`<option value="${u.id}" ${reportUnit===u.id?'selected':''}>${esc(fullUnit(u.id))}</option>`).join('')}</select></div><div class="field"><label>Tìm nhân viên / mã NV</label><input id="reportSearch" placeholder="Nhập mã hoặc tên" value="${esc(reportQuery)}"/></div><button class="btn" id="runReport">Tra cứu</button></div><p class="help mt12">Từ ${dateVN(from)} đến ${dateVN(to)}. Ký hiệu x (chữ thường) dùng cho lượt chấm công chưa đủ theo chế độ đã cấu hình.</p></div><div class="panel"><h3 class="sectiontitle">Bảng tổng hợp</h3><div id="reportTable">${lastReportRows.length?reportTable():'<div class="skeleton">Nhấn “Tra cứu” để lấy số liệu từ máy chủ.</div>'}</div></div>`;
 $$('[data-mode]').forEach(b=>b.onclick=()=>{rangeMode=b.dataset.mode;lastReportRows=[];renderReports(container)});$('#weekend').onchange=e=>{includeWeekend=e.target.checked;lastReportRows=[];renderReports(container)};
 $('#reportAnchor').onchange=e=>{reportAnchor=e.target.value||today();lastReportRows=[];renderReports(container)};
 $('#reportUnit').onchange=e=>{reportUnit=e.target.value;lastReportRows=[];renderReports(container)};
 $('#reportSearch').onchange=e=>reportQuery=e.target.value;
 $('#runReport').onclick=async()=>{reportQuery=$('#reportSearch').value.trim();const b=$('#runReport');b.disabled=true;try{const [a,z]=currentRange();await loadPunches(a,z);$('#reportTable').innerHTML=reportTable();bindReportDetails();notify('Đã tải bảng điểm danh')}catch(err){showError(err)}finally{b.disabled=false}};
 $('#exportExcel').onclick=async()=>{try{reportQuery=$('#reportSearch').value.trim();const [a,z]=currentRange();await loadPunches(a,z);reportTable();exportExcel()}catch(err){showError(err)}};
 bindReportDetails()}
function bindReportDetails(){$$('[data-report-person]').forEach(btn=>btn.onclick=()=>{const empid=btn.dataset.reportPerson,unitid=btn.dataset.reportUnit,[from,to]=currentRange();const rows=punches.filter(p=>p.employee_id===empid&&p.unit_id===unitid&&p.punch_date>=from&&p.punch_date<=to).sort((a,b)=>a.punched_at.localeCompare(b.punched_at));showModal(`<h2>Lịch sử chấm công chi tiết</h2><p class="sub">${esc(lastReportRows.find(x=>x.employee_id===empid)?.full_name||'Nhân viên')} · ${esc(fullUnit(unitid))}</p><div class="tablewrap mt20"><table><thead><tr><th>Ngày</th><th>Lượt</th><th>Thời gian máy chủ</th><th>Điểm quy đổi</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(dateVN(p.punch_date))}</td><td>${esc(slotLabels[p.slot])}</td><td>${esc(new Date(p.punched_at).toLocaleTimeString('vi-VN',{hour12:false,timeZone:'Asia/Ho_Chi_Minh'}))}</td><td>${esc(p.score)}%</td></tr>`).join('')||'<tr><td colspan="4">Chưa có lượt điểm danh</td></tr>'}</tbody></table></div><div class="actions"><button class="btn ghost" data-close>Đóng</button></div>`)})}
function exportExcel(){const {dates,rows}=buildReport();const [from,to]=currentRange();const title=[{v:'AGRIBANK CHI NHÁNH VĨNH PHÚC — BẢNG ĐIỂM DANH TẬP TRUNG',bold:true}];const info=[[...title],[`Kỳ: ${dateVN(from)} - ${dateVN(to)}`],[`Phạm vi: ${labelUnit(reportUnit)||'Toàn hệ thống'}`],[`Ký hiệu: X=đủ cả ngày; Xc=chỉ đủ sáng; Xs=chỉ đủ chiều; x=chưa đủ lượt; -=không có lượt`],[]];
 const header=[{v:'STT',bold:true},{v:'Mã nhân viên',bold:true},{v:'Họ và tên',bold:true},{v:'Đơn vị / phòng ban',bold:true},...dates.map(d=>({v:dateVN(d),bold:true})),...['X','Xc','Xs','x','-'].map(k=>({v:k,bold:true}))];
 const summary=info.concat([header],rows.map((r,i)=>[i+1,r.emp_code,r.full_name,fullUnit(r.unit_id),...dates.map(d=>r.day[d]===undefined?'':r.day[d]),r.counts.X,r.counts.Xc,r.counts.Xs,r.counts.x,r.counts['-']]));
 const raw=[[{v:'CHI TIẾT LƯỢT ĐIỂM DANH (THỜI GIAN MÁY CHỦ)',bold:true}],[],['Mã NV','Họ và tên','Phòng / đơn vị','Ngày','Lượt','Chế độ','Thời gian','Điểm quy đổi']];
 for(const p of punches.filter(p=>!reportUnit||descendants(p.unit_id,reportUnit)).sort((a,b)=>a.punched_at.localeCompare(b.punched_at))){if(reportQuery&&!`${p.emp_code} ${p.full_name}`.toLocaleLowerCase('vi').includes(reportQuery.toLocaleLowerCase('vi')))continue;raw.push([p.emp_code,p.full_name,fullUnit(p.unit_id),dateVN(p.punch_date),slotLabels[p.slot]||p.slot,p.mode,new Date(p.punched_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}),Number(p.score)])}
 const file=makeXlsx([{name:'Tong hop',rows:summary},{name:'Chi tiet luot',rows:raw}]);downloadBlob(new Blob([file],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),`Agribank_Vinh_Phuc_Diem_Danh_${rangeMode}_${from}_${to}.xlsx`);notify('Đã xuất bảng điểm danh Excel')}
function renderSettings(container){const choices=units.filter(u=>u.kind!=='PHONG'&&(profile.role==='root_admin'||profile.role==='cn1_admin'&&descendants(u.id,profile.unit_id)||profile.role==='cn2_admin'&&u.id===profile.unit_id));const sorted=policies.slice().sort((a,b)=>b.effective_from.localeCompare(a.effective_from));container.innerHTML=`<div class="hero"><div><h2>Chọn 2 hoặc 4 lần điểm danh</h2><p>Thiết lập theo từng CN loại I/CN loại II; CN loại II chưa có cấu hình riêng sẽ kế thừa CN loại I. Cấu hình mới có hiệu lực từ ngày mai trở đi.</p></div></div><div class="grid2"><div class="panel"><h3 class="sectiontitle">Thêm quy định có hiệu lực</h3><form id="policyForm"><div class="field"><label>Chi nhánh áp dụng</label><select name="unit_id" required>${choices.map(u=>`<option value="${u.id}">${esc(fullUnit(u.id))}</option>`).join('')}</select></div><div class="grid2"><div class="field"><label>Số lượt/ngày</label><select name="mode" id="modePolicy"><option value="2">2 lượt (sáng / chiều)</option><option value="4">4 lượt (vào / ra 2 buổi)</option></select></div><div class="field"><label>Ngưỡng tương đồng quy đổi</label><select name="threshold"><option value="80">80% (theo yêu cầu)</option><option value="85">85%</option><option value="90">90%</option><option value="95">95%</option></select></div><div class="field"><label>Hiệu lực từ ngày</label><input type="date" name="effective_from" min="${addDay(today(),1)}" value="${addDay(today(),1)}" required/></div><div class="field"><label>Ranh giới sáng/chiều (2 lượt)</label><input type="time" name="split_time" value="12:00" required/></div><div class="field"><label>4 lượt: Bắt đầu sáng ra</label><input type="time" name="am_out_start" value="09:30" required/></div><div class="field"><label>4 lượt: Bắt đầu chiều vào</label><input type="time" name="pm_start" value="12:00" required/></div><div class="field"><label>4 lượt: Bắt đầu chiều ra</label><input type="time" name="pm_out_start" value="15:30" required/></div></div><p class="help mt12">Ngưỡng 80% chỉ là phép quy đổi khoảng cách của mô hình, không phải độ chính xác xác thực được kiểm định.</p><button class="btn mt20">Lưu cấu hình mới</button></form></div><div class="panel"><h3 class="sectiontitle">Lịch sử cấu hình</h3><div class="tablewrap"><table><thead><tr><th>CN</th><th>Hiệu lực</th><th>Lượt</th><th>Ngưỡng</th></tr></thead><tbody>${sorted.map(p=>`<tr><td>${esc(labelUnit(p.unit_id))}</td><td>${esc(dateVN(p.effective_from))}</td><td>${p.mode}</td><td>${p.threshold}%</td></tr>`).join('')}</tbody></table></div></div></div>`;
 $('#policyForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),record={unit_id:fd.get('unit_id'),effective_from:fd.get('effective_from'),mode:Number(fd.get('mode')),threshold:Number(fd.get('threshold')),split_time:fd.get('split_time'),am_out_start:fd.get('am_out_start'),pm_start:fd.get('pm_start'),pm_out_start:fd.get('pm_out_start')};try{if(record.effective_from<=today())throw Error('Chỉ có hiệu lực từ ngày mai');if(!(record.am_out_start<record.pm_start&&record.pm_start<record.pm_out_start))throw Error('Thứ tự mốc giờ không hợp lệ');const {error}=await supabase.from('attendance_policies').insert(record);if(error)postError(error);notify('Đã lên lịch cấu hình mới');await refreshAndRender()}catch(err){showError(err)}}}
function renderAccess(container){const allowedRoles=profile.role==='root_admin'?['root_admin','cn1_admin','cn2_admin','dept_viewer','kiosk']:profile.role==='cn1_admin'?['cn2_admin','dept_viewer','kiosk']:['dept_viewer','kiosk'];const roleOptions=allowedRoles.map(r=>`<option value="${r}">${esc(roleLabels[r])}</option>`).join('');container.innerHTML=`<div class="hero"><div><h2>Phân quyền theo cấp chi nhánh</h2><p>Mỗi người dùng Supabase Auth được gán vai trò và phạm vi riêng. Không thể tự nâng quyền qua giao diện.</p></div></div><div class="grid2"><div class="panel"><h3 class="sectiontitle">Gán quyền tài khoản</h3><div class="hint">Bước 1: Tạo tài khoản Email trong Supabase → Authentication → Users. Bước 2: Sao chép UUID của tài khoản, gán vai trò tại đây. Không tạo tài khoản trực tiếp bằng secret key trong trình duyệt.</div><form id="accessForm"><div class="field"><label>UUID người dùng đã tạo ở Authentication</label><input name="user_id" required pattern="[A-Fa-f0-9-]{36}" placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"/></div><div class="field"><label>Vai trò</label><select name="role" id="roleSelect">${roleOptions}</select></div><div class="field"><label>Đơn vị phân quyền</label><select name="unit_id" id="roleUnit"></select></div><button class="btn mt20">Cấp / cập nhật quyền</button></form></div><div class="panel"><h3 class="sectiontitle">Các tài khoản trong phạm vi</h3><div class="tablewrap"><table><thead><tr><th>UUID</th><th>Vai trò</th><th>Phạm vi</th></tr></thead><tbody>${profiles.map(p=>`<tr><td class="code" title="${esc(p.user_id)}">${esc(p.user_id.slice(0,8))}…</td><td>${esc(roleLabels[p.role])}</td><td>${esc(labelUnit(p.unit_id))}</td></tr>`).join('')}</tbody></table></div><p class="help mt12">Không xuất danh sách tài khoản hoặc khóa truy cập ra kho công khai.</p></div></div>`;
 const roleEl=$('#roleSelect'),unitEl=$('#roleUnit');const change=()=>{const r=roleEl.value,kind=r==='cn1_admin'?'CN1':r==='cn2_admin'?'CN2':r==='dept_viewer'?'PHONG':null;unitEl.innerHTML=(r==='root_admin'?'<option value="">Toàn hệ thống</option>':units.filter(u=>(!kind||u.kind===kind)&& (profile.role==='root_admin'||descendants(u.id,profile.unit_id))).map(u=>`<option value="${u.id}">${esc(fullUnit(u.id))}</option>`).join(''))};roleEl.onchange=change;change();
 $('#accessForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const {error}=await supabase.rpc('assign_user_role',{p_user:String(fd.get('user_id')).trim(),p_role:fd.get('role'),p_unit:fd.get('unit_id')||null});if(error)postError(error);notify('Đã cập nhật quyền truy cập');await refreshAndRender()}catch(err){showError(err)}}}

// Minimal XLSX OOXML generator, carried forward from the prior offline prototype.
function xmlEscape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]))}
function excelColumn(index){let x=index+1,s='';while(x){x--;s=String.fromCharCode(65+x%26)+s;x=Math.floor(x/26)}return s}
function sheetXml(tableRows){const body=tableRows.map((row,ri)=>`<row r="${ri+1}">${row.map((c,ci)=>{if(c===null||c===undefined)return '';const v=typeof c==='object'&&c!==null?c.v:c,style=typeof c==='object'&&c!==null&&c.bold?' s="1"':'';const ref=excelColumn(ci)+(ri+1);if(typeof v==='number'&&Number.isFinite(v))return `<c r="${ref}"${style}><v>${v}</v></c>`;return `<c r="${ref}" t="inlineStr"${style}><is><t xml:space="preserve">${xmlEscape(v)}</t></is></c>`}).join('')}</row>`).join('');return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="15"/><sheetData>${body}</sheetData></worksheet>`}
const CRC_TABLE=(()=>{const t=new Uint32Array(256);for(let i=0;i<256;i++){let c=i;for(let k=0;k<8;k++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);t[i]=c>>>0}return t})();
function checksum(bytes){let c=0xffffffff;for(const b of bytes)c=CRC_TABLE[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function makeZip(files){const encoder=new TextEncoder(),local=[],central=[];let offset=0;let count=0;for(const [path,contents]of files){const name=encoder.encode(path),data=encoder.encode(contents),crc=checksum(data),lh=new Uint8Array(30+name.length),lv=new DataView(lh.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x0800,true);lv.setUint16(8,0,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,name.length,true);lh.set(name,30);local.push(lh,data);const ch=new Uint8Array(46+name.length),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x0800,true);cv.setUint16(10,0,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);ch.set(name,46);central.push(ch);offset+=lh.length+data.length;count++}const centralSize=central.reduce((n,p)=>n+p.length,0),end=new Uint8Array(22),dv=new DataView(end.buffer);dv.setUint32(0,0x06054b50,true);dv.setUint16(8,count,true);dv.setUint16(10,count,true);dv.setUint32(12,centralSize,true);dv.setUint32(16,offset,true);return new Blob([...local,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function makeXlsx(tabs){const files=[];files.push(['[Content_Types].xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${tabs.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`]);files.push(['_rels/.rels',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`]);files.push(['xl/workbook.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${tabs.map((t,i)=>`<sheet name="${xmlEscape(t.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`]);files.push(['xl/_rels/workbook.xml.rels',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${tabs.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${tabs.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`]);files.push(['xl/styles.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Arial"/></font><font><b/><sz val="11"/><color rgb="FF912139"/><name val="Arial"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/></cellXfs></styleSheet>`]);tabs.forEach((t,i)=>files.push([`xl/worksheets/sheet${i+1}.xml`,sheetXml(t.rows)]));return makeZip(files)}
function downloadBlob(blob,filename){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),8000)}

/* Geo-report enhancements: effective ONLY after gps_reporting_migration.sql */
const PROD_RADIUS_M=100, PROD_MAX_GPS_ACCURACY_M=75;
function gpsOnce(){return new Promise((resolve,reject)=>{
 if(!navigator.geolocation)return reject(Error('Trình duyệt không hỗ trợ định vị. Hãy sử dụng HTTPS và cấp quyền vị trí.'));
 navigator.geolocation.getCurrentPosition(resolve,e=>reject(Error(e.code===1?'Bạn chưa cấp quyền GPS chính xác. Từ chối điểm danh.':e.code===3?'GPS hết thời gian phản hồi. Vui lòng thử lại ở nơi thoáng.':'Không lấy được GPS.')), {enableHighAccuracy:true,timeout:16000,maximumAge:0});
})}
function geoDistance(a,b,c,d){const rad=Math.PI/180,x=(c-a)*rad,y=(d-b)*rad,h=Math.sin(x/2)**2+Math.cos(a*rad)*Math.cos(c*rad)*Math.sin(y/2)**2;return 2*6371000*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function currentBranchFromUnit(unitId){let unit=getUnit(unitId),steps=0;while(unit&&steps++<10){if(unit.kind==='CN2'||unit.kind==='CN1')return unit;unit=getUnit(unit.parent_id)}return null}
const oldRenderKioskGPS=renderKiosk;
renderKiosk=function(container){oldRenderKioskGPS(container);const panel=document.createElement('div');panel.className='panel gps-panel mt20';panel.innerHTML=`<h3 class="sectiontitle">📍 Vị trí điểm danh – bán kính 100 m</h3><p class="help">Bắt buộc dùng GPS thiết bị mới trong mỗi lượt điểm danh. Hệ thống xác minh khoảng cách với <b>tọa độ chi nhánh của nhân viên nhận diện</b> và từ chối nếu cách quá 100 m hoặc sai số GPS trên 75 m. Máy chủ quyết định có chấp nhận hay không.</p><button class="btn secondary" id="gpsTest">Kiểm tra GPS</button><div id="gpsResult" class="scanresult mt12">Chưa kiểm tra tọa độ.</div>`;container.append(panel);$('#gpsTest').onclick=async()=>{const out=$('#gpsResult');out.textContent='Đang định vị...';try{const p=await gpsOnce();const u=currentBranchFromUnit(activeScanUnit);const c=p.coords;if(u?.latitude!=null&&u?.longitude!=null){const dist=geoDistance(c.latitude,c.longitude,u.latitude,u.longitude);out.textContent=`Vị trí so với ${u.name}: ${Math.round(dist)} m / 100 m; sai số ±${Math.round(c.accuracy)} m. ${dist<=100&&c.accuracy<=75?'GPS đạt điều kiện sơ bộ.':'⛔ Vị trí chưa đạt điều kiện.'} Phạm vi chính thức được kiểm tra lại theo chi nhánh của nhân viên sau nhận diện.`}else out.textContent=`Đã đọc GPS, sai số ±${Math.round(c.accuracy)} m; chi nhánh đang chọn chưa khai báo tọa độ.`}catch(e){out.textContent='⛔ '+e.message}}};
// UI cannot grant a branch to an arbitrary scan unit; policy still on server.
const oldOrganizationGPS=renderOrganization;
renderOrganization=function(container){oldOrganizationGPS(container);const canEdit=profile?.role==='root_admin'||profile?.role==='cn1_admin';const branches=units.filter(u=>['CN1','CN2'].includes(u.kind));const section=document.createElement('div');section.className='panel mt20';section.innerHTML=`<h3 class="sectiontitle">📍 Tọa độ chi nhánh và bán kính 100 m</h3><p class="help">Mỗi phòng kế thừa vị trí của CN loại I/II trực thuộc. Chỉ quản trị CN loại I cấp trên hoặc quản trị hệ thống mới được sửa tọa độ.</p>${canEdit?`<form id="branchGPS"><div class="grid2"><div class="field"><label>Chọn chi nhánh</label><select id="gpsUnit">${branches.filter(u=>profile.role==='root_admin'||descendants(u.id,profile.unit_id)).map(u=>`<option value="${u.id}">${esc(fullUnit(u.id))}</option>`).join('')}</select></div><div class="field"><label>Bán kính</label><input value="100 mét (cố định)" disabled/></div><div class="field"><label>Vĩ độ</label><input id="gpsLat" type="number" step="any" min="-90" max="90" required/></div><div class="field"><label>Kinh độ</label><input id="gpsLon" type="number" step="any" min="-180" max="180" required/></div></div><div class="row"><button class="btn secondary" type="button" id="geoHere">⌖ Lấy GPS tại vị trí này</button><button class="btn" type="submit">Lưu vị trí chi nhánh</button></div></form>`:''}<div class="tablewrap mt20"><table><thead><tr><th>Chi nhánh</th><th>Tọa độ</th><th>Bán kính</th></tr></thead><tbody>${branches.map(u=>`<tr><td>${esc(fullUnit(u.id))}</td><td>${u.latitude==null?'Chưa nhập':`${Number(u.latitude).toFixed(6)}, ${Number(u.longitude).toFixed(6)}`}</td><td>100 m</td></tr>`).join('')}</tbody></table></div>`;container.append(section);
 if(!canEdit)return;const picker=$('#gpsUnit'),fill=()=>{const u=getUnit(picker.value);$('#gpsLat').value=u?.latitude??'';$('#gpsLon').value=u?.longitude??''};picker.onchange=fill;fill();$('#geoHere').onclick=async()=>{try{const p=await gpsOnce();$('#gpsLat').value=p.coords.latitude.toFixed(7);$('#gpsLon').value=p.coords.longitude.toFixed(7);notify('Đã đọc GPS; kiểm tra chính xác tâm chi nhánh trước khi lưu.')}catch(err){showError(err)}};$('#branchGPS').onsubmit=async e=>{e.preventDefault();try{const {error}=await supabase.rpc('set_branch_coordinates',{p_unit:picker.value,p_lat:Number($('#gpsLat').value),p_lon:Number($('#gpsLon').value)});if(error)postError(error);notify('Đã lưu vị trí chi nhánh (bán kính 100 m)');await refreshAndRender()}catch(err){showError(err)}}
};
const oldAccessGPS=renderAccess;
renderAccess=function(container){oldAccessGPS(container);if(!['root_admin','cn1_admin'].includes(profile?.role))return;const targets=profiles.filter(p=>p.role==='cn2_admin'&&(profile.role==='root_admin'||descendants(p.unit_id,profile.unit_id)));const section=document.createElement('div');section.className='panel mt20';section.innerHTML=`<h3 class="sectiontitle">🔐 Cấp / thu hồi quyền báo cáo CN loại II</h3><p class="help">Quản trị CN loại I được xem dữ liệu các chi nhánh trực thuộc. Quản trị CN loại II chỉ xem/xuất báo cáo của chi nhánh mình sau khi được cấp quyền.</p><div class="tablewrap"><table><thead><tr><th>Tài khoản</th><th>Chi nhánh</th><th>Quyền báo cáo</th><th>Thao tác</th></tr></thead><tbody>${targets.map(p=>`<tr><td class="code" title="${esc(p.user_id)}">${esc(p.user_id.slice(0,10))}…</td><td>${esc(fullUnit(p.unit_id))}</td><td>${p.can_report?'Đã cấp':'Chưa cấp'}</td><td><button class="btn ghost small" data-give-report="${esc(p.user_id)}" data-give-current="${p.can_report?'yes':'no'}">${p.can_report?'Thu hồi':'Cấp quyền'}</button></td></tr>`).join('')||'<tr><td colspan="4">Chưa có tài khoản quản trị CN II</td></tr>'}</tbody></table></div>`;container.append(section);$$('[data-give-report]',section).forEach(b=>b.onclick=async()=>{const grant=b.dataset.giveCurrent!=='yes';try{const {error}=await supabase.rpc('set_reporting_access',{p_user:b.dataset.giveReport,p_enabled:grant});if(error)postError(error);notify(grant?'Đã cấp quyền báo cáo':'Đã thu hồi quyền báo cáo');await refreshAndRender()}catch(err){showError(err)}})
};
// Summary table: year uses aggregated numbers, day/week/month show calendar columns.
reportTable=function(){const {dates,rows}=buildReport();lastReportRows=rows;lastReportDates=dates;const isYear=rangeMode==='year',heading=isYear?'':dates.map(d=>`<th>${esc(dateVN(d))}</th>`).join('');const cells=r=>isYear?'':dates.map(d=>`<td><span class="tag ${markClass(r.day[d])}">${r.day[d]===undefined?'':esc(r.day[d])}</span></td>`).join('');return `<p class="help">${rows.length} dòng nhân viên/đơn vị theo lịch sử phân công. Dấu – là ngày công không có lượt; Xc/Xs là thiếu nửa buổi; x là có lượt nhưng chưa đủ ca. Chưa trừ nghỉ phép, nghỉ lễ, công tác có duyệt.</p><div class="tablewrap"><table class="reportmatrix"><thead><tr><th>Mã NV</th><th>Họ tên</th><th>CN / phòng</th>${heading}<th>X</th><th>Xc</th><th>Xs</th><th>x</th><th>Vắng cả ngày</th><th>Vắng quy đổi*</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="code">${esc(r.emp_code)}</td><td><button class="btn ghost small" data-report-person="${r.employee_id}" data-report-unit="${r.unit_id}">${esc(r.full_name)}</button></td><td>${esc(fullUnit(r.unit_id))}</td>${cells(r)}<td>${r.counts.X||0}</td><td>${r.counts.Xc||0}</td><td>${r.counts.Xs||0}</td><td>${r.counts.x||0}</td><td><b>${r.counts['-']||0}</b></td><td><b>${(r.counts['-']||0)+0.5*((r.counts.Xc||0)+(r.counts.Xs||0))}</b></td></tr>`).join('')||'<tr><td colspan="10">Chưa có dữ liệu trong phạm vi</td></tr>'}</tbody></table></div><p class="help mt12">* Vắng quy đổi = ngày không ghi nhận + 0,5 × (Xc + Xs), chưa tính x. Là số ngày <b>thiếu điểm danh</b> tạm tính, không phải số ngày nghỉ phép thực tế.</p>`};
exportExcel=function(){if(!canReport()){notify('Không có quyền xuất báo cáo',true);return}const {dates,rows}=buildReport(),[a,z]=currentRange();const summ=[[{v:'AGRIBANK VĨNH PHÚC – BÁO CÁO ĐIỂM DANH, NGÀY THIẾU LƯỢT',bold:true}],[`Kỳ ${a} đến ${z}. Số ngày không ghi nhận chưa đối trừ nghỉ được duyệt.`],['Mã NV','Họ tên','Đơn vị','X','Xc','Xs','x','Không ghi nhận cả ngày','Vắng quy đổi']];for(const r of rows)summ.push([r.emp_code,r.full_name,fullUnit(r.unit_id),r.counts.X||0,r.counts.Xc||0,r.counts.Xs||0,r.counts.x||0,r.counts['-']||0,(r.counts['-']||0)+0.5*((r.counts.Xc||0)+(r.counts.Xs||0))]);const detail=[[{v:'BẢNG CHI TIẾT THEO NGÀY',bold:true}],['Mã NV','Họ tên','Đơn vị','Ngày','Ký hiệu']];for(const r of rows)for(const d of dates)if(r.day[d]!==undefined)detail.push([r.emp_code,r.full_name,fullUnit(r.unit_id),d,r.day[d]]);const raw=[[{v:'CÁC LƯỢT ĐÃ GHI TẠI MÁY CHỦ',bold:true}],['Mã NV','Họ tên','Đơn vị','Ngày','Ca','Giờ','GPS cách tâm (m)']];for(const p of punches){if(!rows.some(r=>r.employee_id===p.employee_id&&r.unit_id===p.unit_id))continue;raw.push([p.emp_code,p.full_name,fullUnit(p.unit_id),p.punch_date,slotLabels[p.slot]||p.slot,new Date(p.punched_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}),p.gps_distance_m==null?'':Math.round(p.gps_distance_m)])}const bytes=makeXlsx([{name:'Tong hop',rows:summ},{name:'Chi tiet ngay',rows:detail},{name:'Luot diem danh',rows:raw}]);downloadBlob(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),`Agribank_Vinh_Phuc_Bao_Cao_${rangeMode}_${a}_${z}.xlsx`);notify('Đã xuất Excel theo quyền hiện tại')};

bootstrap();
